// Densidad poblacional - CORREGIDO
function getDensityColor(dens_pobl) {
    return dens_pobl > 85 ? '#800026' :
           dens_pobl > 65  ? '#BD0026' :
           dens_pobl > 45  ? '#E31A1C' :
           dens_pobl > 25  ? '#FC4E2A' :
           dens_pobl > 5   ? '#FD8D3C' :
           '#FFEDA0';
}

function densityStyle(feature) {
    return {
        fillColor: getDensityColor(feature.properties.dens_pobl),
        weight: 2,
        opacity: 1,
        color: 'white',
        dashArray: '3',
        fillOpacity: 0.7
    };
}

function highlightDensityFeature(e) {
    var layer = e.target;
    layer.setStyle({
        weight: 5,
        color: '#666',
        dashArray: '',
        fillOpacity: 0.7
    });
    layer.bringToFront();
}

function resetDensityHighlight(e) {
    densityLayer.resetStyle(e.target);
}

function zoomToDensityFeature(e) {
    mimapa.fitBounds(e.target.getBounds());
}

function onEachDensityFeature(feature, layer) {
    layer.on({
        mouseover: highlightDensityFeature,
        mouseout: resetDensityHighlight,
        click: zoomToDensityFeature
    });
    
    // Agregar popup con información de densidad
    var props = feature.properties;
    layer.bindPopup(
        `<b>Radio: ${props.cod_indec || 'N/A'}</b><br>
         Población total: ${props.p02_tot || 0}<br>
         Densidad: ${props.dens_pobl || 0} hab/ha`
    );
}

// Crear la capa de densidad con la variable correcta
var densityLayer = L.geoJson(dne, {
    style: densityStyle,
    onEachFeature: onEachDensityFeature
}).addTo(mimapa);

// Agregar leyenda de densidad
var legend = L.control({position: 'bottomright'});

legend.onAdd = function(map) {
    var div = L.DomUtil.create('div', 'info legend');
    var grades = [0, 5, 25, 45, 65, 85];
    var labels = [];
    
    div.innerHTML = '<h4>Densidad (hab/ha)</h4>';
    
    for (var i = 0; i < grades.length; i++) {
        div.innerHTML +=
            '<i style="background:' + getDensityColor(grades[i] + 1) + '"></i> ' +
            grades[i] + (grades[i + 1] ? '&ndash;' + grades[i + 1] + '<br>' : '+');
    }
    
    return div;
};

legend.addTo(mimapa);

// Controles
L.control.layers({
    'Open Street Map': osm,
    'Satelital': Esri_WorldImagery
}, {
    'Barrios de Chos Malal': capaBarrios,
    'Densidad poblacional': densityLayer  // Usar la variable correcta
}, {
    position: 'topleft',
    collapsed: true
}).addTo(mimapa);

